from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionQci(EpcSectionGeneric):
    """
    Section "Qci" is a part of epc.lua config file.
    Generated content base on ue.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_qci qci=100 gbr=yes priority=15 delay=80")
    exec("set_qci qci=128 gbr=yes priority=15 delay=80")
    exec("set_qci qci=129 gbr=yes priority=15 delay=80")
    exec("set_qci qci=130 gbr=yes priority=15 delay=80")
    exec("set_qci qci=131 gbr=yes priority=15 delay=80")
    exec("set_qci qci=135 gbr=yes priority=15 delay=80")
    exec("set_qci qci=136 gbr=yes priority=15 delay=80")
    exec("set_qci qci=160 gbr=yes priority=15 delay=80")
    exec("set_qci qci=161 gbr=no priority=15 delay=80")
    exec("set_qci qci=200 gbr=no priority=15 delay=80")
    exec("set_qci qci=253 gbr=yes priority=15 delay=80")
    exec("set_qci qci=254 gbr=yes priority=15 delay=80")
    """

    def _prepare_section_content(self, ue_config, *args, **kwargs):
        logger.debug("Generating QCI section")
        subsection = []
        for qci in sorted(ue_config['qci'].keys()):
            qci_data = ue_config['qci'][qci]
            gbr, priority, delay = qci_data['gbr'], qci_data['priority'], qci_data['delay']

            qci_line = f"set_qci qci={qci} gbr={gbr} priority={priority} delay={delay}"
            subsection.append(EpcLine(line=qci_line, exec=True, tab_count=0))

        sec_op_key_line = f"set_param SEC_OP_KEY={ue_config['UE_RAND']}"
        subsection.append(EpcLine(line=sec_op_key_line, exec=True, tab_count=0))
        self._section_content.append(subsection)
